Source code in <code>db_schema\utils.py</code> <pre><code>def load_model(filepath: str | Path, use_cache: bool = True):
    path = Path(filepath) if isinstance(filepath, str) else filepath

    if path.suffix != ".xml":
        raise ValueError(
            f"Unsupported file format: {path.suffix}. Only .xml files are supported."
        )

    dsbXML = _get_dsbXML()
    if use_cache:
        dsb = _cached_load_model_internal(str(path.resolve()))
    else:
        with open(path, "rb") as f:
            dsb = dsbXML.from_xml(f.read())

    if dsb.site:
        set_site_counter(dsb.site.handle)
    return dsb
